with filtered_payments as (select * from payments where order_id in (1, 27, 28, 37) and status not in ('FAILED', 'REFUNDED')), agg as (select hour(paid_at) as paid_hour, round((100 * sum(case when status = 'FAILED' then 1 else 0 end)) / count(*), 1) as pct_failed, max(paid_at) as latest_paid_at from filtered_payments group by hour(paid_at)) select * from agg order by paid_hour desc;
